    "/api/v1/alerts": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        get?: never;
        put?: never;
        /**
         * Submit one or many alert records
         * @description Accepts a single record object or an array of records. Each
         *     record is run through the configured `core.process_plugins`
         *     pipeline; the response includes the post-pipeline records and
         *     any per-record processing errors.
         *
         *     **Multi-tenant routing** — in a multi-tenant deployment, supply
         *     `Authorization: Bearer <ingest_token>` (the per-tenant opaque token
         *     from `GET /api/v1/tenant/{id}`) to route ingestion to a specific
         *     tenant. When no token is present or the token is unknown, the request
         *     falls back to the `default` tenant. Single-tenant deployments need no
         *     token (existing behaviour preserved).
         *
         *     **Alert federation** — relayed alerts carry an `X-Snooze-Loop` request
         *     header: a comma-separated chain of the `syncer.hostname` server ids the
         *     alert has already traversed. The `forward` plugin appends this server's
         *     id before relaying to a peer; if this server's own id is already in the
         *     chain the alert is accepted and persisted (HTTP 200) but **not**
         *     re-relayed, breaking loops in cyclic (hub-and-spoke / active-active)
         *     topologies. Direct (non-federated) submitters omit the header.
         *
         */
        post: {
            parameters: {
                query?: never;
                header?: {
                    /**
                     * @description Comma-separated chain of `syncer.hostname` server ids a relayed
                     *     alert has already traversed (set by the `forward` federation
                     *     plugin). Omit when submitting alerts directly.
                     *
                     * @example hub-eu,hub-us
                     */
                    "X-Snooze-Loop"?: string;
                };
                path?: never;
                cookie?: never;
            };
            /** @description A record may carry any extra (non-schema) keys; they are preserved and
             *     exposed to rules and templates. The reserved ingest hint
             *     `_preserve_raw: true` copies every extra key into the record's `raw`
             *     field before rules run (the original foreign payload is archived for
             *     audit) and is itself stripped from the stored record. See the
             *     [Custom source mapping](/docs/general/integrations/custom-source) guide.
             *      */
            requestBody: {
                content: {
                    "application/json": components["schemas"]["Record"] | components["schemas"]["Record"][];
                };
            };
            responses: {
                /** @description Per-record processing result. Records that were silently discarded
                 *     (e.g. by a `snooze` discard rule) are omitted from `data` without
                 *     an entry in `errors`. Mixed batches where some records pass and
                 *     some are policy-rejected return 200 with the rejections in `errors`.
                 *      */
                200: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": {
                            data: components["schemas"]["Record"][];
                            errors?: string[];
                        };
                    };
                };
                /** @description All records in the batch were rejected by an enabled `reject` policy
                 *     rule. The response body carries code `policy_rejected` and a message
                 *     containing the matching rule name. Fix the alert or contact the
                 *     operator to adjust the policy rule.
                 *      */
                422: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": components["schemas"]["ErrEnvelope"];
                    };
                };
                503: components["responses"]["IngestDisabled"];
            };
        };
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
